css:
#demo-intro .msg.bubble{ white-space: pre; will-change: transform, opacity; color: var(--ink, #eee);
  background: linear-gradient(var(--accent-soft, #e6a0a622), var(--accent-soft, #e6a0a622)), var(--bg, #111); border-color: color-mix(in srgb, var(--accent, #e6a0a6) 30%, transparent);
  transition: background-color 120ms linear, color 120ms linear; }

#demo-intro .stars{ position: absolute; left: 0; right: 0; top: -420px; bottom: 0; opacity: 0; pointer-events: none; will-change: transform, opacity;
  background-image:
    radial-gradient(1px 1px at 37px 61px, rgba(255,255,255,.7), transparent), radial-gradient(1px 1px at 151px 17px, rgba(255,255,255,.6), transparent),
    radial-gradient(1px 1px at 233px 143px, rgba(255,255,255,.55), transparent), radial-gradient(1px 1px at 91px 211px, rgba(255,255,255,.4), transparent),
    radial-gradient(1.2px 1.2px at 63px 31px, rgba(255,255,255,.75), transparent), radial-gradient(1.2px 1.2px at 181px 97px, rgba(255,255,255,.7), transparent),
    radial-gradient(1.2px 1.2px at 27px 157px, rgba(255,255,255,.65), transparent),
    radial-gradient(1.4px 6px at 111px 83px, rgba(255,255,255,.85), transparent), radial-gradient(1.4px 8px at 307px 251px, rgba(255,255,255,.8), transparent),
    radial-gradient(1.4px 6px at 211px 331px, rgba(255,255,255,.75), transparent);
  background-size: 260px 260px, 260px 260px, 260px 260px, 260px 260px, 200px 200px, 200px 200px, 200px 200px, 400px 400px, 400px 400px, 400px 400px; }

html.demo-intro [data-testid="conn"], html.demo-intro-out [data-testid="conn"], html.demo-opener [data-testid="conn"], html.demo-opener [data-testid="offline-note"],
html.demo-intro [data-testid="activity"][data-phase="reconnecting"], html.demo-intro [data-testid="activity"][data-phase="offline"],
html.demo-opener [data-testid="activity"][data-phase="reconnecting"], html.demo-opener [data-testid="activity"][data-phase="offline"]{ visibility: hidden; }
